#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#define A 512
#define F 64
#define P 2048
#define E 128
#define N 160
typedef struct{char id[N],canonical[N],maturity[32],owns[F][N],pub[F][N],con[F][N];int no,np,nc;}Arch;
typedef struct{char s[N],d[N];}Pair;
typedef struct{char fact[N],producer[N],consumer[N],witness[512],state[64];}RuntimeEvidence;
static void val(const char*l,char*out,size_t n){const char*p=strchr(l,':');size_t i=0;if(!p){*out=0;return;}p++;while(*p==' '||*p=='\t'||*p=='"')p++;while(*p&&*p!='"'&&*p!='\n'&&*p!=','&&i+1<n)out[i++]=*p++;out[i]=0;}
static int ind(const char*s){int n=0;while(*s++==' ')n++;return n;}
static int item(const char*l,char*out,size_t n){const char*p=l;size_t i=0;while(*p==' '||*p=='\t')p++;if(*p!='"')return 0;p++;while(*p&&*p!='"'&&i+1<n)out[i++]=*p++;out[i]=0;return i>0;}
static int arches(const char*path,Arch*a,int*cnt){FILE*f=fopen(path,"r");char l[32768];int in=0,field=0,n=0,cur=-1;if(!f)return 0;while(fgets(l,sizeof l,f)){if(!in){if(strstr(l,"\"architectures\": {"))in=1;continue;}if(strstr(l,"\"interactions\": {"))break;if(ind(l)==4&&strstr(l,"\": {")&&n<A){const char*p=strchr(l,'"'),*q=p?strchr(p+1,'"'):0;size_t z;if(!p||!q)continue;memset(&a[n],0,sizeof a[n]);z=(size_t)(q-p-1);if(z>=N)z=N-1;memcpy(a[n].id,p+1,z);a[n].id[z]=0;cur=n++;field=0;continue;}if(cur<0)continue;if(strstr(l,"\"canonical_name\":")){val(l,a[cur].canonical,sizeof a[cur].canonical);field=0;continue;}if(strstr(l,"\"maturity\":")){val(l,a[cur].maturity,sizeof a[cur].maturity);field=0;continue;}if(strstr(l,"\"owns\": [")){field=1;if(strstr(l,"[]"))field=0;continue;}if(strstr(l,"\"publishes\": [")){field=2;if(strstr(l,"[]"))field=0;continue;}if(strstr(l,"\"consumes\": [")){field=3;if(strstr(l,"[]"))field=0;continue;}if(field&&strchr(l,']')){field=0;continue;}if(field){char v[N];if(item(l,v,sizeof v)){if(field==1&&a[cur].no<F)snprintf(a[cur].owns[a[cur].no++],N,"%s",v);else if(field==2&&a[cur].np<F)snprintf(a[cur].pub[a[cur].np++],N,"%s",v);else if(field==3&&a[cur].nc<F)snprintf(a[cur].con[a[cur].nc++],N,"%s",v);}}}fclose(f);*cnt=n;return 1;}
static int pairs(const char*path,Pair*p,int*cnt){FILE*f=fopen(path,"r");char l[32768],s[N]="",d[N]="";int in=0,n=0;if(!f)return 0;while(fgets(l,sizeof l,f)){if(!in){if(strstr(l,"\"interactions\": {"))in=1;continue;}if(strstr(l,"\"phenotypes\": {"))break;if(strstr(l,"\"destination\":"))val(l,d,sizeof d);else if(strstr(l,"\"source\":")){val(l,s,sizeof s);if(*s&&*d&&n<P){snprintf(p[n].s,N,"%s",s);snprintf(p[n].d,N,"%s",d);n++;*s=*d=0;}}}fclose(f);*cnt=n;return 1;}
static int evidence(const char*path,RuntimeEvidence*e,int*cnt){FILE*f;char l[2048];int n=0;if(!path){*cnt=0;return 1;}f=fopen(path,"r");if(!f)return 0;while(n<E&&fgets(l,sizeof l,f)){char*save=0,*v[5]={0};int k=0;if(l[0]=='#'||l[0]=='\n')continue;for(char*t=strtok_r(l,"\t\n",&save);t&&k<5;t=strtok_r(NULL,"\t\n",&save))v[k++]=t;if(k!=5)continue;snprintf(e[n].fact,N,"%s",v[0]);snprintf(e[n].producer,N,"%s",v[1]);snprintf(e[n].consumer,N,"%s",v[2]);snprintf(e[n].witness,sizeof e[n].witness,"%s",v[3]);snprintf(e[n].state,sizeof e[n].state,"%s",v[4]);n++;}fclose(f);*cnt=n;return 1;}
static int hf(char x[][N],int n,const char*f){for(int i=0;i<n;i++)if(!strcmp(x[i],f))return 1;return 0;}
static int hp(Pair*p,int n,const char*s,const char*d){for(int i=0;i<n;i++)if(!strcmp(p[i].s,s)&&!strcmp(p[i].d,d))return 1;return 0;}
static int mat(const char*m){return !strcmp(m,"implemented")||!strcmp(m,"measured")||!strcmp(m,"proven");}
static int consumer(Arch*a,int n,const char*f){for(int i=0;i<n;i++)if(hf(a[i].con,a[i].nc,f))return 1;return 0;}
static int producer(Arch*a,int n,const char*f){for(int i=0;i<n;i++)if(hf(a[i].owns,a[i].no,f)||hf(a[i].pub,a[i].np,f))return 1;return 0;}
static int evmatch(RuntimeEvidence*e,int n,const char*f,const char*src,const char*dst,RuntimeEvidence**hit){for(int i=0;i<n;i++)if(!strcmp(e[i].fact,f)&&(!src||!strcmp(e[i].producer,"*")||!strcmp(e[i].producer,src))&&(!dst||!strcmp(e[i].consumer,"*")||!strcmp(e[i].consumer,dst))){if(hit)*hit=&e[i];return 1;}return 0;}
static int vis(const char*m,const char*k,const char*a,const char*b,const char*f){return !m||strstr(k,m)||strstr(a?a:"",m)||strstr(b?b:"",m)||strstr(f?f:"",m);}
static void rec(FILE*out,const char*state,const char*a,const char*b,const char*f,const char*ma,const char*mb,const char*w,const char*rs){fprintf(out,"{\"schema\":\"bonfyre-braid-frontier.v2\",\"state\":\"%s\",\"source\":\"%s\",\"destination\":\"%s\",\"fact\":\"%s\",\"source_maturity\":\"%s\",\"destination_maturity\":\"%s\",\"runtime_witness\":\"%s\",\"runtime_state\":\"%s\",\"truth\":\"candidate_or_runtime_evidence_not_owner_contract_or_execution\"}\n",state,a?a:"",b?b:"",f?f:"",ma?ma:"",mb?mb:"",w?w:"",rs?rs:"");}
int main(int ac,char**av){Arch*a=calloc(A,sizeof(*a));Pair*p=calloc(P,sizeof(*p));RuntimeEvidence*e=calloc(E,sizeof(*e));int*in=calloc(A,sizeof(int)),*outd=calloc(A,sizeof(int));int an=0,pn=0,en=0,sum=0,flows=0,wired=0,cand=0,mc=0,sinks=0,shadows=0,op=0,oc=0,uop=0,uoc=0,drift=0;const char*match=0,*outpath=0,*evpath=0;FILE*out=0;char tmp[1024];if(!a||!p||!e||!in||!outd)return 2;if(ac<2)return 2;for(int i=2;i<ac;i++){if(!strcmp(av[i],"--summary"))sum=1;else if(!strcmp(av[i],"--match")&&i+1<ac)match=av[++i];else if(!strcmp(av[i],"--out")&&i+1<ac)outpath=av[++i];else if(!strcmp(av[i],"--runtime-evidence")&&i+1<ac)evpath=av[++i];else return 2;}if(outpath){snprintf(tmp,sizeof tmp,"%s.tmp.%ld",outpath,(long)getpid());out=fopen(tmp,"wb");if(!out)return 2;}if(!arches(av[1],a,&an)||!pairs(av[1],p,&pn)||!evidence(evpath,e,&en))return 2;for(int k=0;k<pn;k++)for(int i=0;i<an;i++){if(!strcmp(a[i].id,p[k].s))outd[i]++;if(!strcmp(a[i].id,p[k].d))in[i]++;}
for(int i=0;i<an;i++){char facts[F*2][N]={{0}};int fn=0;for(int q=0;q<a[i].no;q++)if(!hf(facts,fn,a[i].owns[q]))snprintf(facts[fn++],N,"%s",a[i].owns[q]);for(int q=0;q<a[i].np&&fn<F*2;q++)if(!hf(facts,fn,a[i].pub[q]))snprintf(facts[fn++],N,"%s",a[i].pub[q]);for(int f=0;f<fn;f++){if(!consumer(a,an,facts[f])){RuntimeEvidence*hit=0;op++;if(evmatch(e,en,facts[f],a[i].id,NULL,&hit)){drift++;if(out)rec(out,"runtime_join",a[i].id,hit->consumer,facts[f],a[i].maturity,"",hit->witness,hit->state);if(!sum&&vis(match,"RUNTIME_JOIN",a[i].id,hit->consumer,facts[f]))printf("RUNTIME_JOIN\t%s\t%s\t%s\t%s\t%s\n",a[i].id,hit->consumer,facts[f],hit->state,hit->witness);}else{uop++;if(out)rec(out,"orphan_producer",a[i].id,"",facts[f],a[i].maturity,"","","");if(!sum&&vis(match,"ORPHAN_PUBLISH",a[i].id,0,facts[f]))printf("ORPHAN_PUBLISH\t%s\t%s\t%s\n",a[i].id,facts[f],a[i].maturity);}}for(int j=0;j<an;j++)if(i!=j&&hf(a[j].con,a[j].nc,facts[f])){flows++;if(hp(p,pn,a[i].id,a[j].id))wired++;else{cand++;if(mat(a[i].maturity)&&mat(a[j].maturity))mc++;if(out)rec(out,"candidate_fact_flow",a[i].id,a[j].id,facts[f],a[i].maturity,a[j].maturity,"","");if(!sum&&vis(match,"BRAID_CANDIDATE",a[i].id,a[j].id,facts[f]))printf("BRAID_CANDIDATE\t%s\t%s\t%s\t%s\t%s\n",a[i].id,a[j].id,facts[f],a[i].maturity,a[j].maturity);}}}for(int q=0;q<a[i].nc;q++)if(!producer(a,an,a[i].con[q])){RuntimeEvidence*hit=0;oc++;if(evmatch(e,en,a[i].con[q],NULL,a[i].id,&hit)){drift++;if(out)rec(out,"runtime_join",hit->producer,a[i].id,a[i].con[q],"",a[i].maturity,hit->witness,hit->state);if(!sum&&vis(match,"RUNTIME_JOIN",a[i].id,0,a[i].con[q]))printf("RUNTIME_JOIN\t%s\t%s\t%s\t%s\t%s\n",hit->producer,a[i].id,a[i].con[q],hit->state,hit->witness);}else{uoc++;if(out)rec(out,"orphan_consumer","",a[i].id,a[i].con[q],"",a[i].maturity,"","");if(!sum&&vis(match,"ORPHAN_CONSUME",a[i].id,0,a[i].con[q]))printf("ORPHAN_CONSUME\t%s\t%s\t%s\n",a[i].id,a[i].con[q],a[i].maturity);}}if(in[i]>0&&outd[i]==0){sinks++;if(out)rec(out,"pure_sink",a[i].id,"","",a[i].maturity,"","","");if(!sum&&vis(match,"PURE_SINK",a[i].id,0,0))printf("PURE_SINK\t%s\t%d\t%s\n",a[i].id,in[i],a[i].maturity);}if(*a[i].canonical&&!hf(a[i].owns,a[i].no,a[i].canonical))for(int j=0;j<an;j++)if(i!=j&&hf(a[j].owns,a[j].no,a[i].canonical)){shadows++;if(out)rec(out,"semantic_shadow",a[i].id,a[j].id,a[i].canonical,a[i].maturity,a[j].maturity,"","");if(!sum&&vis(match,"SEMANTIC_SHADOW",a[i].id,a[j].id,a[i].canonical))printf("SEMANTIC_SHADOW\t%s\t%s\t%s\n",a[i].id,a[i].canonical,a[j].id);break;}}
if(out){if(fflush(out)||fsync(fileno(out))||fclose(out)||rename(tmp,outpath)){unlink(tmp);return 2;}}printf("{\"schema\":\"bonfyre-braid-audit.v5\",\"architectures\":%d,\"explicit_interactions\":%d,\"fact_flows\":%d,\"fact_flows_wired\":%d,\"fact_flow_candidates\":%d,\"mature_fact_flow_candidates\":%d,\"declared_orphan_publications\":%d,\"declared_orphan_consumptions\":%d,\"runtime_supported_declaration_drifts\":%d,\"unresolved_orphan_publications\":%d,\"unresolved_orphan_consumptions\":%d,\"pure_sinks\":%d,\"semantic_shadows\":%d,\"frontier_path\":\"%s\",\"truth\":\"runtime_witness_reclassifies_registry_drift_but_never_creates_owner_contract_or_execution\"}\n",an,pn,flows,wired,cand,mc,op,oc,drift,uop,uoc,sinks,shadows,outpath?outpath:"");free(outd);free(in);free(e);free(p);free(a);return 0;}
